APPS=[
L('claude-apps-map','خريطة كل تطبيقات Claude ومنتجاته: أين أستخدم ماذا؟',
 'نظرة شاملة على التطبيق الأساسي وClaude Code والمتصفح وإضافات أوفيس وSlack وواجهة المطورين.',
 ['Claude ليس تطبيقًا واحدًا بل عائلة منتجات تشترك في النماذج نفسها وتختلف في مكان العمل: التطبيق الأساسي للمحادثة والعمل المكتبي، وClaude Code للبرمجة، وClaude في Chrome للمواقع، وإضافات أوفيس وWorkspace لملفاتك، وClaude Tag داخل Slack، وواجهة API لبناء منتجاتك.',
  'اختيار المكان الصحيح يوفر وقتًا أكثر من تحسين البرومت: مهمة جدول بيانات أنسب داخل Excel، ومهمة تعديل مستودع برمجي أنسب في Claude Code، وسؤال سريع أنسب للتطبيق.',
  'هذه الخريطة وصف عام وقت كتابة الدرس؛ المنتجات والمزايا تتطور بسرعة، فراجع صفحات Anthropic الرسمية قبل الاعتماد على ميزة بعينها.'],
 'جدول القرار','عملي: «أريد تلخيص 30 ملف PDF» → التطبيق الأساسي مع Projects.\nعملي: «أصلح خطأ في مستودعي» → Claude Code.\nعملي: «احجز/قارن على موقع يحتاج تسجيل دخولي» → Claude في Chrome.\nعملي: «حلّل جدولًا وأنشئ معادلات» → Claude في Excel.\nعملي: «لخّص نقاش القناة» → Claude Tag في Slack.\nعملي: «أبني بوت لمتجري» → API.',
 'اسأل دائمًا: أين الملف أو البيانات الآن؟ اذهب بـ Claude إليها بدل نقلها.',
 'اكتب ثلاث مهام من أسبوعك الماضي واختر لكل واحدة المنتج الأنسب من الجدول.',
 'مهمتك: تعديل ملف Excel بمعادلات معقدة. ما أنسب مكان؟',
 ['محادثة التطبيق مع نسخ ولصق','Claude داخل Excel','Claude Code','API مباشرة'],1,
 'العمل داخل الأداة التي يعيش فيها الملف يختصر النقل ويحافظ على التنسيق والمعادلات.',
 'ارسم خريطة شخصية: عمودان (مهمة ← منتج) لعشر مهام متكررة.'),

L('claude-web-desktop-mobile','التطبيق الأساسي: ويب وسطح مكتب وجوال',
 'كل ما في Claude الأساسي: المحادثة، الملفات، البحث، Projects، الصوت، الذاكرة والمخرجات.',
 ['التطبيق الأساسي (باسم Claude فقط) متاح على الويب وسطح المكتب والجوال، وهو أول ما تفتحه. فيه المحادثة، رفع الملفات والصور، البحث على الويب، البحث المعمّق للتقارير الطويلة، والمخرجات (Artifacts) كصفحات ومستندات وجداول وعروض تعيش بجانب المحادثة.',
  'Projects تجمع ملفات وتعليمات لموضوع واحد فتبدأ كل محادثة جديدة من سياقك. الذاكرة تحفظ ما يفيد بين المحادثات ويمكنك التحكم بها من الإعدادات، ووضع التصفح الخفي يعمل دون ذاكرة. الوضع الصوتي يتيح الحديث مع Claude، بما في ذلك في السيارة عبر CarPlay.',
  'تطبيق سطح المكتب يضيف الربط بملفات جهازك ومجلداتك ومتصفحك بإذنك، فيصبح Claude قادرًا على إنجاز مهام متعددة الخطوات لا مجرد الرد.'],
 'متى تستخدم Project؟','أنشئ Project باسم «متجري» وارفع: دليل الهوية، قائمة المنتجات، أمثلة عن ردودك.\nالتعليمات: «اكتب بنبرة ودودة وأنهِ كل رد بسؤال واحد، واستخدم أسعار الملف فقط».',
 'كل محادثة جديدة داخل المشروع تبدأ بنفس المعرفة دون إعادة شرح.',
 'أنشئ مشروعًا لمهمة تتكرر عندك أسبوعيًا وجرّب محادثتين فيه.',
 'ما فائدة Projects الأساسية؟',['تغيير النموذج','ثبات السياق والتعليمات عبر محادثات متعددة','زيادة سرعة الإنترنت','حذف الذاكرة'],1,
 'المشروع حاوية معرفة وتعليمات مشتركة تُحمَّل في كل محادثة داخله.',
 'جرّب سؤالًا واحدًا بالبحث على الويب وآخر بدونه وقارن في الدقة والمصادر.'),

L('claude-models-tiers','نماذج Claude: Haiku وSonnet وOpus وFable وMythos',
 'كيف تختار النموذج المناسب بين السرعة والعمق والتكلفة، وما معنى الفئات.',
 ['نماذج Claude تأتي في فئات: Haiku الأسرع والأخف للمهام الكبيرة البسيطة، وSonnet التوازن اليومي بين الذكاء والسرعة، وOpus للمهام الأعمق والأطول، ثم فئة Mythos الأعلى التي تضم Fable للاستخدام العام (مع ضوابط أمان إضافية في الأحياء والأمن السيبراني)، أما Mythos نفسه فمتاح لجهات موثوقة محدودة.',
  'القاعدة: ابدأ بالأخف الذي ينجح. انتقل لنموذج أقوى حين ترى أخطاء استدلال أو سياقًا طويلًا معقدًا أو مهمة متعددة الخطوات. النموذج الأقوى أبطأ وأغلى في الغالب، فلا تدفع ثمن ما لا تحتاجه.',
  'أسماء النماذج وإصداراتها تتغير؛ راجع قائمة النماذج الرسمية في وثائق Anthropic للمعرّفات الحالية قبل كتابة كود.'],
 'سلّم الاختيار','تصنيف 5000 تعليق عميل ← Haiku.\nكتابة منشورات وردود يومية وتحليل جداول ← Sonnet.\nمراجعة عقد طويل أو تصميم نظام معقد ← Opus.\nمهمة بحث وهندسة معقدة جدًا ← فئة Fable عند توفرها لخطتك.',
 'جرّب نفس البرومت على نموذجين قبل أن تقرر؛ الفرق العملي أحيانًا أصغر من المتوقع.',
 'اختر مهمتين من عملك وجرّبهما على نموذجين، ودوّن الفرق في الجودة والزمن.',
 'لتصنيف آلاف الرسائل القصيرة بتكلفة منخفضة، الأنسب غالبًا:',['أقوى نموذج دائمًا','نموذج خفيف وسريع','لا حاجة لنموذج','Mythos'],1,
 'المهام البسيطة المتكررة لا تحتاج أعلى عمق، والتكلفة والسرعة تحسمان.',
 'اصنع جدولًا: مهمة / النموذج المجرَّب / النتيجة / التكلفة التقريبية.'),

L('claude-code-complete','Claude Code الكامل: من الطرفية إلى الويب والجوال',
 'وكيل برمجة يقرأ مشروعك وينفذ ويختبر: التثبيت، CLAUDE.md، الأذونات، الوكلاء الفرعيون، الخطافات وMCP.',
 ['Claude Code وكيل برمجة يعمل من الطرفية، وأيضًا من الويب وسطح المكتب والجوال. يقرأ ملفات مشروعك، يشغّل الأوامر، يعدّل الشيفرة، ويجري الاختبارات، ويمكنه فتح طلبات الدمج على GitHub بإذنك.',
  'ملف CLAUDE.md في جذر المشروع هو دليل الفريق لـ Claude: أوامر البناء، أسلوب الكتابة، ما لا يُلمس. كل ما تكتبه هناك يُقرأ في كل جلسة. الأذونات تتحكم بما يُنفَّذ دون سؤال، والخطافات (Hooks) تشغّل أوامر تلقائيًا عند أحداث معينة كالتنسيق بعد كل تعديل.',
  'الوكلاء الفرعيون يقسّمون المهمة الكبيرة (بحث متوازٍ، مراجعة) كلٌّ بسياقه الخاص، وخوادم MCP تربطه بأدوات خارجية كقاعدة بياناتك أو متتبع المهام.'],
 'جلسة عمل نموذجية','١) «اقرأ المشروع واشرح بنية الملفات في 10 أسطر».\n٢) «اقترح خطة لإضافة صفحة الدفع دون تنفيذ».\n٣) وافق ثم: «نفّذ الخطوة 1 وشغّل الاختبارات».\n٤) «راجع التغييرات كما يراجعها زميل قبل الدمج».',
 'الخطة أولًا ثم التنفيذ بخطوات صغيرة مع اختبارات تقلل الأخطاء الصامتة.',
 'اكتب CLAUDE.md من 10 أسطر لمشروع تعرفه: الأوامر، الأسلوب، المحظورات.',
 'ما وظيفة ملف CLAUDE.md؟',['تخزين كلمات السر','إرشادات دائمة للمشروع يقرؤها Claude كل جلسة','نسخة احتياطية','قائمة المستخدمين'],1,
 'هو سياق ثابت للمشروع؛ ولهذا لا يوضع فيه أسرار.',
 'اطلب من Claude Code خطة فقط لتحسين صغير في مشروعك دون تنفيذ، وراجع الخطة.'),

L('claude-in-chrome-browser','Claude في Chrome والمتصفح: العمل على المواقع',
 'ماذا يفعل Claude داخل المتصفح، ومتى يطلب إذنك، وكيف تحمي حسابك.',
 ['Claude في Chrome إضافة تتيح لـ Claude أن يتصفح المواقع بدلك ضمن متصفحك وجلساتك المفتوحة: يقرأ الصفحات، يملأ النماذج، ينقر، ويقارن بين مواقع. وهو مفيد حين لا يوجد موصل مباشر لتطبيقك.',
  'الأمان هنا جوهري: محتوى الصفحة بيانات لا أوامر. قد تحتوي صفحة أو بريد على نص يحاول توجيه Claude (حقن البرومت)، لذلك يجب ألا ينفذ ما يجده في الصفحات دون موافقتك. أبقِ تأكيد الشراء والإرسال والحذف لنفسك دائمًا.',
  'ابدأ بمهام قراءة وبحث ومقارنة، ثم النماذج والإدخال بعد أن تثق بنمط عمله، وراقب ما يفعله في اللحظات الأولى.'],
 'مهمة آمنة','«افتح مواقع ثلاثة متاجر منافسة وأخرج لي أسعار المنتج X وشروط الشحن في جدول. لا تُنفّذ أي شراء أو تسجيل».',
 'حدّد في الطلب ما هو ممنوع صراحة (شراء، إرسال، حذف).',
 'جرّب مهمة قراءة فقط: مقارنة مواصفات ثلاثة منتجات من صفحاتها.',
 'ماذا تفعل لو طلبت صفحة من Claude تنفيذ أمر غير طلبك؟',['ينفذ فورًا','يعتبره بيانات ويسألك قبل أي إجراء','يحذف الصفحة','يغلق المتصفح'],1,
 'المحتوى الخارجي ليس مصدر أوامر؛ الأوامر من المستخدم فقط.',
 'اكتب قائمة من خمسة إجراءات لن تسمح لـ Claude بتنفيذها دون تأكيدك.'),

L('claude-office-addins','Claude في Excel وPowerPoint وWord وOutlook وGoogle Workspace',
 'العمل على ملفاتك من داخلها: معادلات وعروض ومستندات وبريد.',
 ['إضافات Claude لحزمة Microsoft 365 تعمل داخل Excel وPowerPoint وWord وOutlook، وهناك تكامل مع Google Workspace. ميزتها أنك لا تنقل الملف: يقرأ Claude محتواه الحالي ويعدّل ضمنه.',
  'في Excel: شرح معادلات، بناء نماذج، تنظيف بيانات. في PowerPoint: تحويل مذكرة إلى عرض وتحسين الشرائح. في Word: صياغة وتحرير مع حفظ التنسيق. في Outlook: تلخيص سلاسل بريد ومسودات ردود تراجعها قبل الإرسال.',
  'قاعدة ثابتة: الأرقام والبريد المرسل مسؤوليتك؛ راجع المعادلات بحالة اختبار صغيرة، ولا ترسل مسودة دون قراءتها.'],
 'طلب في Excel','«في العمود D مبيعات شهرية. أضف عمود نمو شهري %، ولوّن أقل 3 أشهر، وأعطني ملخصًا بسطرين. اشرح المعادلة التي استخدمتها».',
 'اطلب شرح المعادلة لتتحقق منها وتتعلمها.',
 'جرّب إضافة واحدة على ملف حقيقي صغير ونسخة احتياطية.',
 'أهم ميزة للعمل داخل Excel بدل اللصق في المحادثة؟',['شكل أجمل','يقرأ ويعدّل الملف الحقيقي بمعادلاته','أرخص','بدون إنترنت'],1,
 'العمل على الملف نفسه يحفظ المعادلات والتنسيق ويقلل أخطاء النقل.',
 'حوّل جدولك الأسبوعي إلى ملخص تنفيذي من شريحتين بمساعدة إضافة PowerPoint.'),

L('claude-slack-tag-teams','Claude Tag وSlack: Claude عضوًا في الفريق',
 'وكيل جماعي داخل قنوات الفريق: متى يفيد وكيف تحكمه.',
 ['Claude Tag وكيل جماعي يعمل داخل أدوات تعاون الفريق، ويتوفر حاليًا على Slack. يمكن للفريق أن يذكره في قناة ليلخّص نقاشًا، يصيغ ردًا، يبحث، أو يتابع مهمة، ويرى الجميع العمل نفسه.',
  'قوة هذا النمط أن السياق جماعي: لا نسخ ولصق بين أشخاص. وخطره أن الأذونات جماعية أيضًا، فحدّد ما يصل إليه من قنوات وأدوات، ومن يملك صلاحية طلب الإجراءات.',
  'ضع عادات فريق: صيغة طلب موحدة، وتسمية القرارات، وعدم لصق بيانات حساسة في قنوات واسعة.'],
 'طلب في قناة','«@Claude لخّص نقاش آخر 24 ساعة في قرارات وأسئلة مفتوحة ومسؤول كل بند».',
 'اطلب مخرجات بصيغة ثابتة: قرارات / أسئلة / مهام.',
 'اتفقوا كفريق على ثلاث مهام فقط يُسمح لـ Claude بها في القناة.',
 'ما الاحتياط الأهم عند استخدام وكيل داخل قناة فريق؟',['اسم جميل','ضبط ما يصل إليه من قنوات وصلاحيات','إيقاف الإشعارات','رفع الخط'],1,
 'الوكيل الجماعي يرى ويفعل ضمن أذونات مشتركة، فالحوكمة قبل التوسع.',
 'اكتب سياسة من خمسة أسطر لاستخدام Claude في قنوات شركتك.'),

L('claude-api-console','واجهة API ولوحة Console: ابنِ منتجك',
 'من المفاتيح إلى أول طلب، واستدعاء الأدوات، والتخزين المؤقت والدفعات.',
 ['واجهة Claude البرمجية تتيح دمج النماذج في تطبيقك أو بوت متجرك. تدخل Console لإنشاء مفتاح وضبط حدود الإنفاق ومراقبة الاستخدام، ثم ترسل رسائل إلى نقطة Messages محددًا النموذج وأقصى طول للرد.',
  'أهم المفاهيم: رسالة النظام (تعليمات دائمة)، استدعاء الأدوات (Tool use) ليستدعي النموذج دوالّك، الدفعات (Batch) لمهام ضخمة غير عاجلة بتكلفة أقل، والتخزين المؤقت للبرومت لتخفيض كلفة السياق المتكرر، والتدفق (Streaming) لعرض الرد تدريجيًا.',
  'لا تضع المفتاح في شيفرة الواجهة الأمامية أبدًا؛ مكانه الخادم أو متغيرات البيئة. وراجع وثائق docs.claude.com لأسماء النماذج والحدود الحالية.'],
 'أول طلب (Python)','import anthropic\nclient = anthropic.Anthropic()\nr = client.messages.create(\n    model="claude-sonnet-5-5",\n    max_tokens=500,\n    system="أنت مساعد متجر يرد بإيجاز وبالعربية.",\n    messages=[{"role":"user","content":"ما سياسة الإرجاع؟"}])\nprint(r.content[0].text)',
 'المفتاح يُقرأ من متغير البيئة ANTHROPIC_API_KEY ولا يُكتب في الشيفرة.',
 'أنشئ مفتاحًا تجريبيًا بحد إنفاق صغير ونفّذ الطلب أعلاه.',
 'أين يوضع مفتاح API؟',['في شيفرة الصفحة','على الخادم أو متغير بيئة','في منشور','في اسم الملف'],1,
 'من يملك المفتاح يستهلك رصيدك، فلا يظهر للمتصفح.',
 'صمّم رسالة نظام لبوت يجيب عن أسئلة الشحن فقط ويحوّل ما سواها لبشري.'),

L('claude-connectors-skills-plugins','الموصلات وMCP والمهارات والإضافات (Plugins)',
 'كيف تربط Claude بتطبيقاتك وتعلّمه إجراءات فريقك.',
 ['الموصلات (Connectors) تربط Claude بتطبيقاتك: بريد، تقويم، ملفات، مهام، قواعد بيانات، عبر بروتوكول MCP المفتوح. حين يوجد موصل فهو أدق وأسرع من التصفح اليدوي.',
  'المهارات (Skills) مجلدات تعليمات تعلّم Claude طريقة محددة لإنجاز نوع عمل (قالب تقرير، مراجعة عقد، بناء ملف Excel بمعاييرك) وتُحمَّل عند الحاجة. الإضافات (Plugins) تجمع مهارات وأوامر وموصلات لوظيفة أو فريق كامل.',
  'ابدأ بموصل واحد تستخدمه يوميًا، ثم حوّل أي مهمة تكررها كل أسبوع إلى مهارة بدل إعادة شرحها.'],
 'من مهمة متكررة إلى مهارة','١) نفّذ المهمة يدويًا مرة مع Claude حتى تنجح.\n٢) اطلب: «اكتب لي هذه الخطوات كمهارة قابلة لإعادة الاستخدام: متى تُستخدم، المدخلات، الخطوات، نقاط التحقق».\n٣) احفظها وجرّبها على حالة جديدة.',
 'المهارة الجيدة تحدد نقاط التوقف للموافقة البشرية.',
 'اختر مهمة أسبوعية وحوّلها إلى مهارة من 6 خطوات.',
 'الفرق بين الموصل والمهارة؟',['لا فرق','الموصل يصل لتطبيق/بيانات والمهارة تعلّم طريقة عمل','المهارة أغلى','الموصل للصور'],1,
 'الموصل = وصول، المهارة = إجراء. يجتمعان في الإضافة.',
 'حدد موصلين تحتاجهما وسبب كل منهما قبل ربطهما.'),

L('claude-science-security-industries','Claude Science وSecurity وحزم القطاعات',
 'منتجات متخصصة للعلماء وفرق الأمن وقطاعات القانون والمال.',
 ['Claude Science منصة عمل للباحثين تُدار على أجهزة المختبر نفسها، تساعد في قراءة الأدبيات وتحليل البيانات وكتابة الأوراق. Claude Security يفحص قواعد الشيفرة بحثًا عن الثغرات ويقترح إصلاحات لفرق الأمن.',
  'أما «Claude للقانون» و«للخدمات المالية» وغيرهما فهي طريقة تغليف تجمع مهارات وموصلات لقطاع معين، لا منتجات منفصلة بنماذج مختلفة.',
  'في القطاعات المنظمة ركّز على: ما البيانات المسموح إدخالها، من يراجع المخرجات، وسجل ما جرى. المنتج يسرّع العمل ولا يلغي المسؤولية المهنية.'],
 'قائمة تحقق قطاعية','• هل البيانات تحتوي معلومات عملاء أو مرضى؟\n• من المراجع البشري قبل الاعتماد؟\n• أين تُحفظ المخرجات وسجلها؟\n• هل تسمح السياسة الداخلية بالأداة؟',
 'ابدأ بالمهام عالية الحجم منخفضة المخاطر.',
 'اكتب قائمة تحقق من أربعة بنود لقطاعك قبل إدخال أي بيانات حساسة.',
 'ما حدود استخدام Claude في قطاع منظم؟',['لا حدود','يسرّع ولا يلغي المراجعة المهنية','للتسلية','بدلاً من المختص'],1,
 'المسؤولية القانونية والمهنية تبقى على الإنسان.',
 'حدد ثلاث مهام منخفضة المخاطر في قطاعك تصلح بداية.'),

L('claude-privacy-plans-admin','الخطط والخصوصية والإدارة: تحكم في بياناتك',
 'الذاكرة والوضع الخفي وإعدادات البيانات وإدارة الفرق.',
 ['تتحكم من الإعدادات في توليد الذاكرة من المحادثات، ويمكنك حذف ما حُفظ أو إيقاف الميزة. وضع التصفح الخفي لا يستخدم الذاكرة. ولا تفترض أن كل خطة تشمل المزايا نفسها: تختلف حدود الاستخدام والمزايا بين الخطط الفردية والفرق والمؤسسات.',
  'مالكو الفرق والمؤسسات يديرون الوصول والموصلات وإعدادات الشبكة والقدرات من لوحة الإدارة، ويحددون ما يُسمح به لموظفيهم.',
  'للتفاصيل الدقيقة (الحدود، الأسعار، سياسة الاحتفاظ بالبيانات) استخدم مركز المساعدة الرسمي support.claude.com بدل الاعتماد على الذاكرة أو على منشورات غير رسمية.'],
 'عادات خصوصية','• لا تلصق كلمات سر ولا أرقام بطاقات.\n• أخفِ أسماء العملاء وأرقام هواتفهم عند التحليل.\n• راجع الذاكرة المحفوظة دوريًا.\n• استعمل الوضع الخفي للمواضيع الحساسة.',
 'القاعدة: لا تُدخل ما لا تقبل أن يُرى.',
 'افتح إعدادات الذاكرة واقرأ ما حُفظ وعدّله.',
 'أين تجد الحدود والأسعار الدقيقة؟',['منشور عشوائي','مركز المساعدة الرسمي','توقّع','مجموعة واتساب'],1,
 'المصدر الرسمي يتحدث دائمًا ويحدد التفاصيل.',
 'اكتب سياسة خصوصية شخصية من خمس نقاط لاستخدامك لـ Claude.'),

L('claude-choose-your-setup','تصميم منظومتك: خطة 30 يومًا لتتقن Claude',
 'اختر منتجاتك، وابنِ العادات، وقِس الأثر في أربعة أسابيع.',
 ['لا تحتاج كل المنتجات. اختر مجموعة صغيرة تغطي عملك: منتج أساسي للمحادثة، منتج مكاني لأهم ملفاتك (إضافة أوفيس أو Code)، وموصل واحد للبيانات. الأسبوع الأول لتعلّم الأساسيات، الثاني لمشاريع وتعليمات، الثالث لربط الأدوات، الرابع للأتمتة والقياس.',
  'قِس الأثر بأرقام: زمن المهمة قبل وبعد، عدد مرات إعادة العمل، رضا من يستلم المخرجات. ما لا يوفّر وقتًا بعد أسبوعين يُترك أو يُعدَّل.',
  'ثم عمّم: درّب زميلًا، شارك مهاراتك، وحدّث الخطة كلما ظهرت ميزة جديدة تستحق التجربة.'],
 'خطة الأسابيع الأربعة','الأسبوع 1: التطبيق الأساسي + أول Project.\nالأسبوع 2: تعليمات وقوالب، ورفع ملفات.\nالأسبوع 3: موصل واحد + إضافة أوفيس أو Code.\nالأسبوع 4: مهارة مؤتمتة + قياس الوقت الموفَّر.',
 'تجربة واحدة جديدة كل أسبوع أفضل من عشر تجارب مبعثرة.',
 'اكتب خطتك الشخصية للأسابيع الأربعة ومؤشر نجاح واحد لكل أسبوع.',
 'كيف تحكم على نجاح أداة جديدة؟',['شعور عام','قياس الزمن والجودة قبل وبعد','عدد الميزات','اسمها'],1,
 'القياس يميّز الأداة المفيدة من المبهرة.',
 'سجّل زمن مهمة متكررة قبل وبعد أسبوعين من الاستخدام المنظم.'),
]
MODULES_APPS=[
 ['المستوى 9 · تطبيقات Claude ومنتجاته بالتفصيل','خريطة كل المنتجات: التطبيق الأساسي، النماذج، Claude Code، المتصفح، أوفيس، Slack، API، الموصلات، القطاعات، الخصوصية وخطتك الشخصية.',[l['slug'] for l in APPS]],
]
